parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "first_name": { "type": "string", "description": "The sender's first name, from their signature or the From line. Empty string if not stated." },
    "last_name": { "type": "string", "description": "The sender's surname. Empty string if not stated." },
    "email": { "type": "string", "description": "The best reply-to address. Prefer one written in the signature; otherwise the address in the From line." },
    "phone": { "type": "string", "description": "Phone number if one is given, otherwise an empty string." },
    "company": { "type": "string", "description": "The company or organisation they are writing on behalf of. Empty string if not stated." },
    "city": { "type": "string", "description": "Town or city of the premises, if mentioned. Empty string otherwise." },
    "office_size_sqft": { "type": "number", "description": "Size of the premises in square feet as a plain number, e.g. 4200 for '4,200 sq ft'. Use 0 if no size is given - never guess one." },
    "cleaning_frequency": { "type": "string", "description": "How often they want cleaning, in their own words, e.g. 'three evenings a week'. Empty string if not stated." },
    "summary": { "type": "string", "description": "One or two sentences saying what they are asking for, including any start date and budget they mention." }
  },
  "required": ["email", "summary"]
}

parameters.jsCode:
// Turn what was read out of the email into the standard lead.
//
// The sender's own address is the fallback for the email field: the extraction
// can miss a signature, but the From line is always there, and a lead we
// cannot reply to is useless.

function addressFrom(fromLine) {
  const match = String(fromLine || '').match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  return match ? match[0].toLowerCase() : '';
}

const emails = $('A lead email arrives').all();

return $input.all().map((item, index) => {
  const raw = emails[index]?.json || emails[0]?.json || {};
  // Gmail returns capitalised header names (From, Subject); other paths use
  // lower case. Accept both rather than depending on which one turns up.
  // With Simplify off, `from` is a parsed object ({ value: [...], text }),
  // not a string, so take its text form.
  const mail = {
    from: raw.From || raw.from?.text || raw.from || '',
    subject: raw.Subject || raw.subject || '',
    id: raw.id || '',
  };
  const found = item.json?.output || item.json || {};

  const size = Number(found.office_size_sqft) || null;

  return {
    json: {
      lead: {
        lead_id: `lead_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
        received_at: new Date().toISOString(),
        source: 'email',
        source_detail: 'inbox',
        first_name: String(found.first_name || '').trim(),
        last_name: String(found.last_name || '').trim(),
        email: String(found.email || '').trim().toLowerCase() || addressFrom(mail.from),
        phone: String(found.phone || '').trim(),
        company: String(found.company || '').trim(),
        website: '',
        office_size_sqft: size,
        cleaning_frequency: String(found.cleaning_frequency || '').trim(),
        city: String(found.city || '').trim(),
        // The subject is kept with the summary: "Cleaning quote for our clinic"
        // is often the clearest sentence in the whole email.
        message: [mail.subject, found.summary].filter(Boolean).join(' - '),
        raw: { from: mail.from, subject: mail.subject, id: mail.id, extracted: found },
      },
    },
  };
});
